(function(){'use strict';const production=window.omnibloomHost!=null;document.documentElement.dataset.obProduction=String(production);window.OBEnvironment=Object.freeze({production});
function preview(node){if(!production||node.nodeType!==1)return;const list=[...(node.matches('[data-preview]')?[node]:[]),...node.querySelectorAll('[data-preview]')];for(const e of list){if(!e.hidden)e.hidden=true;if(!e.hasAttribute('inert'))e.setAttribute('inert','');if(e.contains(document.activeElement))document.activeElement.blur();}}
function glyphs(){try{return window.omnibloomHost?.getGlyphs?.()||document.documentElement.dataset.glyphs||localStorage.getItem('ob.glyphs')||'xbox';}catch{return 'xbox';}}
function hints(){for(const bar of document.querySelectorAll('.hintbar')){let move=[...bar.children].find(e=>e.tagName==='SPAN'&&/D-pad/.test(e.textContent));if(!move){move=document.createElement('span');move.textContent='D-pad Move';bar.prepend(move);}else if(move.textContent!=='D-pad Move')move.textContent='D-pad Move';const accept=bar.querySelector('[data-glyph=accept]')?.closest('span'),back=bar.querySelector('[data-glyph=back]')?.closest('span');if(bar.firstElementChild!==move)bar.prepend(move);if(accept&&move.nextElementSibling!==accept)move.after(accept);if(back&&(accept||move).nextElementSibling!==back)(accept||move).after(back);for(const child of bar.children)if(child.tagName==='SPAN'){child.classList.add('ob-hint-item');for(const n of child.childNodes)if(n.nodeType===3){const text=n.textContent.replace(/\s*·\s*/g,' ');if(text!==n.textContent)n.textContent=text;}}}for(const bar of document.querySelectorAll('.hint')){const text='D-pad Move · '+(glyphs()==='playstation'?'× Select · ○ Back':'A Select · B Back');if(bar.textContent!==text)bar.textContent=text;}}
function status(button,text){let e=button.parentElement.querySelector('[data-file-status]');if(!e){e=document.createElement('p');e.dataset.fileStatus='';e.setAttribute('role','status');button.after(e);}e.textContent=text;}
async function pick(button){const input=document.getElementById(button.dataset.hostFile),purpose=button.dataset.purpose,maxBytes=purpose==='captions'?1048576:52428800;try{if(typeof window.omnibloomHost?.request!=='function')throw Error('Files picker unavailable');button.disabled=true;const reply=await window.omnibloomHost.request({version:1,id:'files-'+Date.now(),method:'files.pick',params:{purpose,accept:input.accept,multiple:input.multiple,maxBytes}});if(reply?.ok!==true)throw Error(reply?.code||'Files picker unavailable');const result=reply.result;if(result?.cancelled){status(button,'No file selected.');return;}const rows=result instanceof File?[result]:result?.files;if(!Array.isArray(rows)||!rows.length||rows.length>(input.multiple?20:1))throw Error('Files picker did not return readable files');const files=rows.map(row=>{if(row instanceof File){if(row.size>maxBytes)throw Error('Selected file exceeds the viewer limit');return row;}if(!row||typeof row.name!=='string'||!row.name||row.name.length>255||/[\\/\0]/.test(row.name)||typeof row.type!=='string')throw Error('Invalid file metadata');let bytes=row.bytes;if(Array.isArray(bytes)){if(bytes.length>maxBytes||bytes.some(n=>!Number.isInteger(n)||n<0||n>255))throw Error('Invalid file bytes');bytes=Uint8Array.from(bytes);}if(!(bytes instanceof Uint8Array)||bytes.byteLength>maxBytes)throw Error('The host must resolve this file handle to bounded bytes');return new File([bytes],row.name,{type:row.type});});if(files.reduce((n,f)=>n+f.size,0)>maxBytes)throw Error('Selected files exceed the combined viewer limit');const transfer=new DataTransfer();files.forEach(f=>transfer.items.add(f));input.files=transfer.files;input.dispatchEvent(new Event('change',{bubbles:true}));status(button,'File selection delivered to the viewer.');}catch(e){status(button,e.message);}finally{button.disabled=typeof window.omnibloomHost?.request!=='function';}}
document.addEventListener('DOMContentLoaded',()=>{preview(document.documentElement);hints();for(const button of document.querySelectorAll('[data-host-file]')){button.hidden=!production;button.disabled=typeof window.omnibloomHost?.request!=='function';button.addEventListener('click',()=>pick(button));}new MutationObserver(records=>{let hintChange=false;for(const record of records){if(record.type==='attributes')preview(record.target);for(const node of record.addedNodes||[])preview(node);if(record.target.nodeType===1&&record.target.closest('.hintbar,.hint')||record.target.parentElement?.closest('.hintbar,.hint'))hintChange=true;}if(hintChange)hints();}).observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['hidden','inert']});});
})();
